select `d`.`id` AS `id`,(case when (0 = `s`.`verification_enabled`) then 9223372036854775807 when (`d`.`verified_until` <= 0) then 0 when (0 = `s`.`verification_expires`) then 9223372036854775807 else (`d`.`checked_at` + `s`.`verification_validity_seconds`) end) AS `eligible_until`,((0 = `s`.`verification_enabled`) or (`d`.`verified_until` > 0)) AS `serves`,`s`.`verification_enabled` AS `verification_required`,(case when ((0 <> `s`.`verification_enabled`) and (0 <> `s`.`verification_expires`) and (`d`.`verified_until` > 0)) then (`d`.`checked_at` + `s`.`verification_validity_seconds`) else NULL end) AS `expires_at` from (`ruphish_domains` `d` join `ruphish_settings` `s`) where (`s`.`id` = 1)
